# Exact-match 410 list for archived pages.
# Load this file in the http context (Dockerfiles copy it into conf.d).
# $uri is the normalized, decoded path without the query string.
# Each page is listed with and without a trailing slash. This is not a prefix match.
# nginx map lookup is case-insensitive, so /sli and /slo also match the retired
# /SLI and /SLO aliases. Uppercase duplicates are omitted because they conflict.
# Root placeholders are from 7a278f0 (447 pages). Legacy English pages are from
# d247101 (486 pages, /en/<category>/<slug>). Pending Chinese pages are from
# 7316d49 (516 pages: 193 material + 323 dropped, /<category>/<slug>).
# Seed, category index, about, privacy, and English seed URLs are not listed.
# Batch 3 stores decoded Chinese paths because $uri is already decoded.
# 8192: 4096 could not build an optimal hash after this batch (2898 keys).
map_hash_max_size 8192;
# 256 still holds the longest key, now 113 bytes
# (/linux/prometheus-metric-builder-utf8-支持含-utf-8-字符的标签名在-group-by-查询中未被引号转义/).
# nginx cannot build this map at 128 (the previous longest /en/ key was 112 bytes).
map_hash_bucket_size 256;
